
package dev.prasad.json;
import java.util.*; import dev.prasad.json.JsonValue.*;
public class Json {
  public static JsonValue parse(String text){ Parser p=new Parser(text); p.ws(); JsonValue v=p.value(); p.ws(); if(!p.end()) throw p.err("trailing characters"); return v; }
  public static String stringify(JsonValue v){ StringBuilder sb=new StringBuilder(); write(v,sb); return sb.toString(); }
  static void write(JsonValue v,StringBuilder sb){ if(v instanceof JsonObject o){ sb.append('{'); boolean first=true; for(var e:o.entries().entrySet()){ if(!first) sb.append(','); first=false; writeString(e.getKey(),sb); sb.append(':'); write(e.getValue(),sb);} sb.append('}'); } else if(v instanceof JsonArray a){ sb.append('['); for(int i=0;i<a.items().size();i++){ if(i>0) sb.append(','); write(a.items().get(i),sb);} sb.append(']'); } else if(v instanceof JsonString s){ writeString(s.value(),sb); } else if(v instanceof JsonNumber n){ sb.append(n.raw()); } else if(v instanceof JsonBoolean b){ sb.append(b.value()); } else sb.append("null"); }
  static void writeString(String s,StringBuilder sb){ sb.append('"'); for(char c: s.toCharArray()){ switch(c){ case '"': sb.append("\\\""); break; case '\\': sb.append("\\\\"); break; case '\n': sb.append("\\n"); break; case '\r': sb.append("\\r"); break; case '\t': sb.append("\\t"); break; default: if(c<0x20) sb.append(String.format("\\u%04x",(int)c)); else sb.append(c); } } sb.append('"'); }
  static class Parser { final String s; int pos; Parser(String s){this.s=s;} boolean end(){return pos>=s.length();} JsonParseException err(String m){return new JsonParseException(m+" at "+pos);} void ws(){ while(!end() && Character.isWhitespace(s.charAt(pos))) pos++; }
    JsonValue value(){ if(end()) throw err("unexpected end"); char c=s.charAt(pos); return switch(c){ case '{'->object(); case '['->array(); case '"'->new JsonString(string()); case 't'->{ expect("true"); yield JsonValue.TRUE; } case 'f'->{ expect("false"); yield JsonValue.FALSE; } case 'n'->{ expect("null"); yield JsonValue.NULL; } default->number(); }; }
    void expect(String lit){ if(!s.startsWith(lit,pos)) throw err("expected "+lit); pos+=lit.length(); }
    JsonObject object(){ pos++; ws(); var m=new LinkedHashMap<String,JsonValue>(); if(!end() && s.charAt(pos)=='}'){pos++; return new JsonObject(m);} while(true){ ws(); String k=string(); ws(); if(end()||s.charAt(pos)!=':') throw err("expected :"); pos++; ws(); m.put(k,value()); ws(); if(end()) throw err("unterminated object"); char c=s.charAt(pos++); if(c=='}') break; if(c!=',') throw err("expected , or }"); } return new JsonObject(m); }
    JsonArray array(){ pos++; ws(); var list=new ArrayList<JsonValue>(); if(!end() && s.charAt(pos)==']'){pos++; return new JsonArray(list);} while(true){ ws(); list.add(value()); ws(); if(end()) throw err("unterminated array"); char c=s.charAt(pos++); if(c==']') break; if(c!=',') throw err("expected , or ]"); } return new JsonArray(list); }
    String string(){ if(end() || s.charAt(pos)!='"') throw err("expected string"); pos++; StringBuilder sb=new StringBuilder(); while(!end()){ char c=s.charAt(pos++); if(c=='"') return sb.toString(); if(c=='\\'){ if(end()) break; char e=s.charAt(pos++); switch(e){ case '"': sb.append('"'); break; case '\\': sb.append('\\'); break; case '/': sb.append('/'); break; case 'n': sb.append('\n'); break; case 't': sb.append('\t'); break; case 'r': sb.append('\r'); break; case 'b': sb.append('\b'); break; case 'f': sb.append('\f'); break; case 'u': if(pos+4>s.length()) throw err("bad unicode escape"); sb.append((char)Integer.parseInt(s.substring(pos,pos+4),16)); pos+=4; break; default: throw err("bad escape"); } } else sb.append(c); } throw err("unterminated string"); }
    JsonNumber number(){ int start=pos; if(!end() && s.charAt(pos)=='-') pos++; while(!end() && "0123456789.eE+-".indexOf(s.charAt(pos))>=0) pos++; if(start==pos) throw err("invalid value"); String raw=s.substring(start,pos); try{ Double.parseDouble(raw);}catch(Exception e){ throw err("invalid number "+raw);} return new JsonNumber(raw); }
  }
  public static class JsonParseException extends RuntimeException { public JsonParseException(String m){super(m);} }
}
